INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('9990bc4d-2e19-48fa-9dea-37ded9499440', 'Nasheeda', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 1, true, true, '2026-08-01T06:18:34.547479+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 5, 'അറബി ഭാഷയിലെ ഇസ്‌ലാമിക ഗാനങ്ങളാണ് അവതരിപ്പിക്കേണ്ടത് ഒരാൾക്ക് ദഫ് പശ്ചാത്തല വാദ്യമായി ഉപയോഗിക്കാം.', '5 മിനുട്ട്', 'അക്ഷരസ്ഫുടത: 30, ഭാവം: 25, ശ്രുതിലയം: 20, താളം: 25') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('795511d1-f26a-46d9-bd00-c754c1869450', 'Panel Discussion', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 1, true, true, '2026-08-01T06:18:35.360675+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 5, 'നിർദ്ദേശിക്കുന്ന സാഹിത്യ കൃതി സമഗ്രമായി വായിച്ചാണ് മത്സരത്തിനെത്തേണ്ടത്.നിശ്ചയിക്കുന്ന കൃതിയുടെ ആശയ വിനിമയം ഉൾക്കൊള്ളുന്ന ചർച്ചയാണ് നടക്കേണ്ടത്.', '60 മിനുട്ട്', 'ചർച്ചയിലെ പെർഫോമൻസ് കൂടി പരിഗണിച്ചാണ് വിജയിയെ തീരുമാനിക്കുക: , മത്സരാർത്ഥിയുടെ വായനക്ഷമത: , സാഹിത്യ ശേഷി: , ഇടപെടലിലെ മികവ്: ') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('9b8e763e-5b41-4127-a3cd-e98a6f60a92f', 'Mathrbhasha', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 4, true, false, '2026-08-01T06:18:35.75643+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'off-stage', 1, 'മാതൃഭാഷയായ മലയാളത്തിൽ മാത്രമേ മത്സര സമയം മത്സരിക്കാൻ സാധിക്കൂ.രണ്ട് സെലെക്ഷൻ ആയിരിക്കും മത്സരം.സെക്ഷൻ 1:നൽകുന്ന വിഷയത്തിൽ രണ്ട് മിനുറ്റ് ഇടതടവില്ലാതെ സംസാരിക്കുക.സെക്ഷൻ 2:വിധികർത്താക്കൾ ചോദിക്കുന്ന ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുക', '60 മിനുട്ട്', 'വേഗത,സാഹിത്യം,വ്യക്തത,മാധുര്യം') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('7de75303-cc4d-43e9-95ec-4b12615a8d27', 'Va''alu', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 3, true, false, '2026-08-01T06:18:34.760086+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'പരമ്പരാഗത ശൈലിയിലുള്ള മതപ്രഭാഷണം ആണ് അവതരിപ്പിക്കേണ്ടത് മത്സരത്തിൻ്റെ മുമ്പ് വിഷയം നിർണയിച്ചു നൽകും.', '10 മിനുട്ട്', 'തനിമ: 15, അക്ഷരസ്ഫുടത: 20, കലാത്മകത: 20, ഉദ്ധരണി: 10, ശബ്ദനിയന്ത്രണം: 15, സംസാരിക്കാനുള്ള കഴിവ്: 20') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('dc30665a-e6f0-456d-8278-6566353cac6c', 'Elocution Urd', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 2, true, false, '2026-08-01T06:18:36.342844+00:00', '5f786eeb-f198-4857-a4f4-8840d31fbb75', NULL, 'stage', 1, 'മത്സരത്തിന് നൽകുന്ന വിഷയത്തിൽ ആശയം അവതരിപ്പിക്കുക. ഭാഷ: ഉറുദു', '5 മിനുട്ട്', 'അക്ഷരസ്ഫു‌ടത: 15, ഭാഷ ശുദ്ധി: 15, വിഷയം: 20, കലാത്മകത: 15, ശബ്ദനിയന്ത്രണം: 15, സംസാരിക്കാനുള്ള കഴിവ്: 20') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('f0f0c64d-d003-49c1-a73c-502325045dde', 'Ted Talk', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 3, true, false, '2026-08-01T06:18:35.94559+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'സദസ്സിനെ കൂടുതൽ അഭിമുഖീകരിക്കാൻ പറ്റുന്ന തരം സ്റ്റേജിലൂടെ നടന്നുള്ള പ്രസൻറേഷനാണ് TED Talk .പോഡിയവും പി പി ടിിയും ഇച്ഛാനുസൃതം ഉപയോഗിക്കാവുന്നതാണ്.', '7 മിനുട്ട്', 'മനഃപാഠം: 30, അവതരണ ഭംഗി: 30, ഭാഷ: 20, ഓഡിയൻസ് കോൺടാക്ട്: 20') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('e27dd27f-ceca-4d31-a61b-f4eff289a17d', 'Revolutionary Song', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 1, true, true, '2026-08-01T06:18:36.140065+00:00', NULL, NULL, 'stage', 3, 'ധർമ പ്രചോദിതരാവാൻ പ്രേരകമായ ഗാനങ്ങൾ അവതരിപ്പിക്കുക.പുതിയ രചനകൾക്ക് പ്രാധാന്യം നൽകണ.രചനയിലും അവതരണത്തിലും മൗലികതക്കും പുതുമക്കും പ്രാമുക്യം നൽകുക', '5 മിനുട്ട്', 'സാഹിത്യം: 25, ശ്രുതിലയം: 25, അംഗംങ്ങൾ തമ്മിലുള്ള യോജിപ്പ്: 20, സ്വരം: 20, മൗലികത: 10') ON CONFLICT DO NOTHING;
