INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('ffb2ce05-3206-406a-ad86-b96eb7820fee', 'Iftha''a', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 2, false, false, '2026-08-01T06:18:40.875408+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'off-stage', 1, 'മസ്അല കണ്ടെത്തലും ഫത്വവ രൂപത്തിൽ വിവിധ തലങ്ങൾ പരാമർശിച്ച് കൊണ്ടുള്ള വിശദീകരണം നൽകലുമാണ് മത്സരം.ശാഫിഈ മദ്ഹബിലെ ആധികാരിക ഗ്രന്ഥങ്ങളെ അടിസ്ഥാനമാക്കിയാണ് മസ്അല കണ്ടെത്തേണ്ടത്', '40 മിനുട്ട്', 'പൂർണ്ണത,റഫറൻസ്,ഭാഷാശൈലി') ON CONFLICT DO NOTHING;
