INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('7216da98-7930-4e8d-91d8-8abcacf79910', 'Madh Ganam', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, true, false, '2026-08-01T06:18:52.192371+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'പ്രവാചകന്മാർ, സ്വഹാബിവര്യർ എന്നിവരെ മദ്ഹ് ചെയ്‌തുള്ള ഗാനങ്ങൾ അവതരിപ്പിക്കുക.', '5 മിനുട്ട്', 'സാഹിത്യം: 25, താളം: 25, ശ്രുതിലയം: 25, സ്വരം: 25') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('2ac4f11b-47e0-4bbd-bb1c-38a4fbf0cbd5', 'Typing', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 4, false, false, '2026-08-01T06:18:38.8325+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'off-stage', 1, 'നിർണയിച്ചു നൽകുന്ന ഭാഗകങ്ങൾ കൃത്യമായി ടൈപ്പ് ചെയ്തുതീർക്കുക.കൃത്യത വേഗത പൂർത്തീകരണം എന്നിവ പരിഗണിച്ചാണ് വിധി നിർണയം', '2 മിനുട്ട്', 'കൃത്യത,വേഗത,പൂർത്തീകരണം') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('b4d0b439-6d34-43d3-9418-df6114ba583f', 'Quiz', 'f4836f20-4c0c-4748-8ea8-4ce7d0c292bd', 3, false, false, '2026-08-01T06:18:58.328964+00:00', '3ed74f87-6fb2-41c7-8f2d-3de66a9e09c3', NULL, 'off-stage', 1, 'ക്വിസ് മാസ്റ്റർ ചോദ്യം ചോദിക്കുകയും മത്സരാർത്ഥികൾ ഉത്തരം എഴുതുകയും ചെയ്യുന്നതാണ് നല്ലരീതി. എഴുതുന്നതിനാവശ്യമായ പേപ്പർ പ്രോഗ്രാം കമ്മിറ്റി സിൽ പതിച്ചു കൊടുക്കണം. ഉത്തരമെഴുതാനുള്ള സമയം ക്വിസ് മാസ്റ്റർക്ക് അനുവദിക്കാം. സമയം കഴിഞ്ഞാൽ ബെല്ലടിക്കുകയോ പറയുകയോചെയ്യാം. വ്യത്യസ്‌തഉത്തരങ്ങൾക്ക് സാധ്യതയുള്ള ചോദ്യങ്ങൾ പരമാവധി ഒഴിവാക്കുക. നിശ്ചിത ചോദ്യം കഴിഞ്ഞാൽ ഒരേ മാർക്കുള്ള ഒന്നിലധികം പേർ വന്നാൽ വിജയികളെ കണ്ടെത്തുന്നതിന് ഒരേ മാർക്ക് നേടിയവരോട് വീണ്ടും ചോദ്യം ചോദിച്ച് അവരിൽ നിന്ന് വിജയികളെ തെരഞ്ഞെടുക്കേണ്ടതാണ്. മത്സരത്തിലെ ചോദ്യങ്ങൾ സമകാലികം, പൊതു വിജ്ഞാനം, ചരിത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 50 ശതമാനവും മെൻ്റൽ എബിലിറ്റി, ശാസ്ത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 30 ശതമാന വും ഇസ്‌ലാം, പ്രാസ്ഥാനികം എന്നീ ഏരിയകളിൽ നിന്ന് 20 ശതമാന വും ആയിരിക്കണം.', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('e37711f6-3ade-48a5-81b0-e72486dd4b1f', 'Magazine', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 1, false, true, '2026-08-01T06:18:39.420905+00:00', 'f0f93738-2ecc-49d2-a14d-a3ac113cd919', NULL, 'off-stage', 5, 'നേരത്തെ നൽകുന്ന വിഷയത്തിൽ മാഗസിൻ നിര്മിക്കുന്നതാണ് മത്സരം മലയാള ഭാഷയിൽ ലിഖിത രൂപത്തിൽ ആയിരിക്കണം. ചുരുങ്ങിയത് 30 പേജെങ്കിലും വേണം', '12 ദിവസം', 'ആശയം,ആവിഷ്‌കാരം,ഭാഷ,സംവിധാനം,റഫറൻസ്') ON CONFLICT DO NOTHING;
