INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('a762aded-4800-4d6b-9fe2-d7842c37e5dd', 'Thahfeezul Burdha', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 4, false, false, '2026-08-01T06:18:39.86174+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'off-stage', 1, 'തഹ്ഫീളുൽ ബുർദഃ : ഇമാം ബുസൂരി (റ)വിൻ്റെ ഖസീദതുൽ ബുർദയുടെ ഹിഫ്ള്, ആശയം മുതലായവ അടിസ്ഥാനമാക്കിയായിരിക്കും മത്സരം. ഒരാൾക്ക് 3 ചാൻസ്. ആദ്യഘട്ടത്തിൽ ആലോചനാ സമയം ഒരു മിനുട്ട്. പിന്നീട് 30 സെക്കന്റും മൂന്നാം ഘട്ടത്തിൽ 15 സെക്കൻ്റും ആയിരിക്കും', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('afbd7967-5aca-454a-b3b8-75d45b750233', 'Elocution Arb', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 2, true, false, '2026-08-01T06:18:47.50211+00:00', '5f786eeb-f198-4857-a4f4-8840d31fbb75', NULL, 'stage', 1, 'മത്സരത്തിന് നൽകുന്ന വിഷയത്തിൽ ആശയം അവതരിപ്പിക്കുക. ഭാഷ: അറബി.', '5 മിനുട്ട്', 'അക്ഷരസ്ഫു‌ടത: 15, ഭാഷ ശുദ്ധി: 15, വിഷയം: 20, കലാത്മകത: 15, ശബ്ദനിയന്ത്രണം: 15, സംസാരിക്കാനുള്ള കഴിവ്: 20') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('8657065d-b9c3-439d-9020-cf46fbba72d6', 'quiz', 'd85a7367-6d26-4504-a26c-e50093111330', 3, true, false, '2026-08-01T06:18:43.178604+00:00', '5f786eeb-f198-4857-a4f4-8840d31fbb75', NULL, 'off-stage', 1, 'ക്വിസ് മാസ്റ്റർ ചോദ്യം ചോദിക്കുകയും മത്സരാർത്ഥികൾ ഉത്തരം എഴുതുകയും ചെയ്യുന്നതാണ് നല്ലരീതി. എഴുതുന്നതിനാവശ്യമായ പേപ്പർ പ്രോഗ്രാം കമ്മിറ്റി സിൽ പതിച്ചു കൊടുക്കണം. ഉത്തരമെഴുതാനുള്ള സമയം ക്വിസ് മാസ്റ്റർക്ക് അനുവദിക്കാം. സമയം കഴിഞ്ഞാൽ ബെല്ലടിക്കുകയോ പറയുകയോചെയ്യാം. വ്യത്യസ്‌തഉത്തരങ്ങൾക്ക് സാധ്യതയുള്ള ചോദ്യങ്ങൾ പരമാവധി ഒഴിവാക്കുക. നിശ്ചിത ചോദ്യം കഴിഞ്ഞാൽ ഒരേ മാർക്കുള്ള ഒന്നിലധികം പേർ വന്നാൽ വിജയികളെ കണ്ടെത്തുന്നതിന് ഒരേ മാർക്ക് നേടിയവരോട് വീണ്ടും ചോദ്യം ചോദിച്ച് അവരിൽ നിന്ന് വിജയികളെ തെരഞ്ഞെടുക്കേണ്ടതാണ്. മത്സരത്തിലെ ചോദ്യങ്ങൾ സമകാലികം, പൊതു വിജ്ഞാനം, ചരിത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 50 ശതമാനവും മെൻ്റൽ എബിലിറ്റി, ശാസ്ത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 30 ശതമാന വും ഇസ്‌ലാം, പ്രാസ്ഥാനികം എന്നീ ഏരിയകളിൽ നിന്ന് 20 ശതമാന വും ആയിരിക്കണം.', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('09a03246-fa2b-4c1c-a2f6-306674653020', 'Article Preveiw', 'd85a7367-6d26-4504-a26c-e50093111330', 3, false, false, '2026-08-01T06:18:45.797649+00:00', 'f0f93738-2ecc-49d2-a14d-a3ac113cd919', NULL, 'off-stage', 1, 'പ്രോഗ്രാം കമ്മിറ്റി നൽകുന്ന ആർട്ടിക്കിൾ വായിച്ച് സംക്ഷിപ്‌തമായി പരിചയപ്പെടുത്തുക.', '40 മിനുട്ട്', 'ആശയം, സാഹിത്യം, ഖണ്ഡികാകരണം') ON CONFLICT DO NOTHING;
