INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('73eac066-3cce-4715-aeca-af2e28016b37', 'Elocution Mal', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 3, true, false, '2026-08-01T06:18:47.098429+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'മത്സരത്തിന് നൽകുന്ന വിഷയത്തിൽ ആശയം അവതരിപ്പിക്കുക. ഭാഷ: മലയാളം.', '5 മിനുട്ട്', 'അക്ഷരസ്ഫു‌ടത: 15, ഭാഷ ശുദ്ധി: 15, വിഷയം: 20, കലാത്മകത: 15, ശബ്ദനിയന്ത്രണം: 15, സംസാരിക്കാനുള്ള കഴിവ്: 20') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('3d41213d-7b3d-449b-8ad1-7b32e2263017', 'Haikku', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 4, false, false, '2026-08-01T06:18:49.106811+00:00', 'eb0e7540-114e-4218-9d47-2c872090bfbb', NULL, 'off-stage', 1, 'തലക്കെട്ട് അടക്കം നാലുവരിയിൽ ഉൾക്കൊള്ളിക്കണം.', '20 മിനിറ്റ്', 'ആശയം, സാഹിത്യം, ഭാഷ') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('9dc312e5-64da-40e8-96aa-ae8314406290', 'Spelling Bea', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:53.576192+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'ഇംഗ്ലീഷ് വാക്കുകളുടെ സ്പെല്ലിങ് അടിസ്ഥാനപ്പെടുത്തിയുള്ള മത്സരമാണ് സ്‌പെല്ലിംഗ് ബീ യോഗ്യനായ ഒരാളെ (സ്‌പെല്ലിംഗ് ബീ മാസ്റ്റർ)മത്സര നിയന്ത്രണത്തിന് ഏൽപ്പിക്കുക.രണ്ട് ഘട്ടങ്ങൾ ആയിട്ടാണ് മത്സരം നടക്കേണ്ടത്. ഇംഗ്ലീഷ് ഉച്ചാരണം അറിയുന്ന ആളായിരിക്കണം സ്പെല്ലിങ് ബീ മാസ്റ്റർ.ഘട്ടം:1 ഇംഗ്ലീഷ് വാക്കുകളുടെ ഒരു ലിസ്റ്റ് തെയ്യാർ ചെയ്യുക.വാക്കുകളുടെ എണ്ണം മാസ്റ്റർക്ക് തീരുമാനിക്കാം.ലിസ്റ്റിലെ വാക്കുകൾ മാസ്റ്റർ ഉച്ചരിക്കുക.ഉച്ചരിച്ച വാക്കിന്റെ സ്‌പെല്ലിംഗ് മത്സരാർത്ഥി എഴുതുക.ഘട്ടം:2 വാക്കുകളെ കുറിച്ചുള്ള ചോദ്യങ്ങൾ തെയ്യാർ ചെയ്യുക. അവയുടെ ഉത്തരമായി നാൽ ഓപ്ഷൻ കൊടുക്കുക ഓപ്ഷനുകളിൽ നിന്ന് ശെരിയായ ഉത്തരം മത്സരാർത്ഥി സെലക്ട് ചെയ്ത് എഴുതുക.രണ്ട് ഘട്ടങ്ങളിലുമായി ഏറ്റവും കൂടുതൽ സ്കോർ ലഭിച്ച മത്സരാർത്ഥിയാണ് വിജയ്', '', '') ON CONFLICT DO NOTHING;
