INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('0e552f1b-32b4-4e88-9370-0b45da5b93b3', 'Reading Hindi', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:56.046992+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'ഹിന്ദി ഭാഷയിലെ പുസ്തകങ്ങളിൽ നിന്ന് വിധികർത്താക്കൾ നിർണയിച്ച് നൽകുന്ന ഭാഗം വായിക്കുക.മത്സരത്തിന് 10 മിനുട്ട് മുമ്പ് ഓരോ മത്സരാർത്ഥിക്കും ഭാഗം നിർണയിച്ച് നൽകണം', '5 മിനുട്ട്', 'വായനയുടെ താളം,അക്ഷരസ്ഫുടത,ആശയഗ്രഹണം,ശബ്ദ ക്രമീകീകരണം,ഭാവ വ്യത്യാസം') ON CONFLICT DO NOTHING;
