INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('d8771511-4749-4ff0-83e7-e8c08074e4f3', 'Essay Mal', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 4, false, false, '2026-08-01T06:18:49.746771+00:00', 'eb0e7540-114e-4218-9d47-2c872090bfbb', NULL, 'off-stage', 1, 'വിഷയം മത്സര ഹാളിൽ വച്ച് നൽകും. ഭാഷ : മലയാളം.', '30 മിനിറ്റ്', 'ഭാഷാലാളിത്യം, വസ്‌തുതകളുടെ വിന്യാസം, അവതരണ മികവ്, വിഷയത്തിലുള്ള അറിവ്, റഫറൻസ്') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('48abc9ac-a4e8-40d5-8b5d-19b94d64c44d', 'Language Game', 'f4836f20-4c0c-4748-8ea8-4ce7d0c292bd', 3, false, false, '2026-08-01T06:18:59.114964+00:00', '3ed74f87-6fb2-41c7-8f2d-3de66a9e09c3', NULL, 'off-stage', 1, 'ലാംഗ്വേജ് ഗെയിം : ഭാഷാ പ്രയോഗ ശേഷിയും പദസമ്പത്തും പരിശോധിക്കുന്ന ഈ മത്സരത്തിന് പദ ചങ്ങലനിർമ്മാണവും രണ്ടാം ഘട്ടത്തിൽ നിശ്ചിത പദങ്ങളുപയോഗിച്ച് വാചക നിർമ്മാണവുമാണ് വേണ്ടത്. പദചങ്ങലയിൽ ഒരു പദം ബോർഡിലെഴുതുക.അതിൻ്റെ അവസാന അക്ഷരത്തിൽ തുടങ്ങുന്ന പദം മത്സരാർത്ഥികൾ നിർമിക്കണം. അങ്ങനെ ഓരോ പദത്തിൻ്റെയും അവസാന അക്ഷരത്തിൽ തുടങ്ങുന്ന പദങ്ങൾ നിർമ്മിക്കലാണ് മത്സരം.നാമങ്ങളാണ് പദചങ്ങലയിൽ എഴുതേണ്ടത്. വ്യക്തികളുടെയോ നാടുകളുടെയോ പേരുകൾ പരിഗണിക്കില്ല. അഞ്ച് മിനുട്ട് കൊണ്ട് മത്സരാർത്ഥികൾ പരമാവധി പദങ്ങളെഴുതണം. ചങ്ങല മുറിയുന്നിടത്ത് വെച്ച് മാർക്ക് അവസാനിപ്പിക്കേണ്ടതാണ്', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('fc6c6207-d0de-4658-8904-1aa1d987a567', 'Volley Word', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 4, true, false, '2026-08-01T06:18:50.571258+00:00', 'eb0e7540-114e-4218-9d47-2c872090bfbb', NULL, 'stage', 1, 'അർത്ഥസഹിതം noun (സ്ഥലം, വ്യക്തി ,നാമങ്ങൾ ഒഴികെ) മാത്രമായിരിക്കും പരിഗണിക്കുക', '', 'വ്യക്തത: , പൂർണ്ണത: , അർത്ഥ ധാരണ: ') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('2b8d0097-02da-4c10-a9cc-c08fe999b1f0', 'Quiz', 'c277087c-e6c2-4961-aa4c-b3a0f5f7735e', 3, false, false, '2026-08-01T06:19:02.170849+00:00', '33c4c6e7-206c-4600-86dd-780cc3097598', NULL, 'off-stage', 1, 'ക്വിസ് മാസ്റ്റർ ചോദ്യം ചോദിക്കുകയും മത്സരാർത്ഥികൾ ഉത്തരം എഴുതുകയും ചെയ്യുന്നതാണ് നല്ലരീതി. എഴുതുന്നതിനാവശ്യമായ പേപ്പർ പ്രോഗ്രാം കമ്മിറ്റി സിൽ പതിച്ചു കൊടുക്കണം. ഉത്തരമെഴുതാനുള്ള സമയം ക്വിസ് മാസ്റ്റർക്ക് അനുവദിക്കാം. സമയം കഴിഞ്ഞാൽ ബെല്ലടിക്കുകയോ പറയുകയോചെയ്യാം. വ്യത്യസ്‌തഉത്തരങ്ങൾക്ക് സാധ്യതയുള്ള ചോദ്യങ്ങൾ പരമാവധി ഒഴിവാക്കുക. നിശ്ചിത ചോദ്യം കഴിഞ്ഞാൽ ഒരേ മാർക്കുള്ള ഒന്നിലധികം പേർ വന്നാൽ വിജയികളെ കണ്ടെത്തുന്നതിന് ഒരേ മാർക്ക് നേടിയവരോട് വീണ്ടും ചോദ്യം ചോദിച്ച് അവരിൽ നിന്ന് വിജയികളെ തെരഞ്ഞെടുക്കേണ്ടതാണ്. മത്സരത്തിലെ ചോദ്യങ്ങൾ സമകാലികം, പൊതു വിജ്ഞാനം, ചരിത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 50 ശതമാനവും മെൻ്റൽ എബിലിറ്റി, ശാസ്ത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 30 ശതമാന വും ഇസ്‌ലാം, പ്രാസ്ഥാനികം എന്നീ ഏരിയകളിൽ നിന്ന് 20 ശതമാന വും ആയിരിക്കണം.', '', '') ON CONFLICT DO NOTHING;
