INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('84d8db81-9324-4407-ace4-77d9da8d2779', 'Poem Writing', 'c277087c-e6c2-4961-aa4c-b3a0f5f7735e', 3, false, false, '2026-08-01T06:19:01.335914+00:00', '33c4c6e7-206c-4600-86dd-780cc3097598', NULL, 'off-stage', 1, 'ആശയം മത്സര ഹാളിൽ വച്ച് നൽകും.', '30 മിനിറ്റ്', 'ഭാഷ, സർഗാത്മകത, സൗന്ദര്യാത്മകത, പ്രതിപാദന രീതി, താളം') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('b1ae2619-71c2-4dbd-a1a5-b83381d714b4', 'Quiz', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:54.605839+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'ക്വിസ് മാസ്റ്റർ ചോദ്യം ചോദിക്കുകയും മത്സരാർത്ഥികൾ ഉത്തരം എഴുതുകയും ചെയ്യുന്നതാണ് നല്ലരീതി. എഴുതുന്നതിനാവശ്യമായ പേപ്പർ പ്രോഗ്രാം കമ്മിറ്റി സിൽ പതിച്ചു കൊടുക്കണം. ഉത്തരമെഴുതാനുള്ള സമയം ക്വിസ് മാസ്റ്റർക്ക് അനുവദിക്കാം. സമയം കഴിഞ്ഞാൽ ബെല്ലടിക്കുകയോ പറയുകയോചെയ്യാം. വ്യത്യസ്‌തഉത്തരങ്ങൾക്ക് സാധ്യതയുള്ള ചോദ്യങ്ങൾ പരമാവധി ഒഴിവാക്കുക. നിശ്ചിത ചോദ്യം കഴിഞ്ഞാൽ ഒരേ മാർക്കുള്ള ഒന്നിലധികം പേർ വന്നാൽ വിജയികളെ കണ്ടെത്തുന്നതിന് ഒരേ മാർക്ക് നേടിയവരോട് വീണ്ടും ചോദ്യം ചോദിച്ച് അവരിൽ നിന്ന് വിജയികളെ തെരഞ്ഞെടുക്കേണ്ടതാണ്. മത്സരത്തിലെ ചോദ്യങ്ങൾ സമകാലികം, പൊതു വിജ്ഞാനം, ചരിത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 50 ശതമാനവും മെൻ്റൽ എബിലിറ്റി, ശാസ്ത്രം എന്നീ ഏരിയകളിൽ നിന്ന് 30 ശതമാന വും ഇസ്‌ലാം, പ്രാസ്ഥാനികം എന്നീ ഏരിയകളിൽ നിന്ന് 20 ശതമാന വും ആയിരിക്കണം.', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('dc2262aa-c2e5-4660-9939-b44e1e2556fd', 'Essay Mal', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:55.224041+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'വിഷയം മത്സര ഹാളിൽ വച്ച് നൽകും. ഭാഷ : മലയാളം.', '30 മിനിറ്റ്', 'ഭാഷാലാളിത്യം, വസ്‌തുതകളുടെ വിന്യാസം, അവതരണ മികവ്, വിഷയത്തിലുള്ള അറിവ്, റഫറൻസ്') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('e4a183c1-7184-480a-b840-dd872c0e8e61', 'Book Test', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 2, false, false, '2026-08-01T06:18:56.253556+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'നിർദ്ദേശിക്കുന്ന ഐ.പി.ബി പുസ്തകം മത്സരാർത്ഥി നേരത്തെ വായിച്ചിരിക്കണം.  പ്രിൻ്റ് ചെയ്ത ചോദ്യാവലിയിൽ ആകെ 15 ചോദ്യങ്ങളാണ് ഉണ്ടാവുക.', '20 മിനുട്ട്', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('1f22849f-17e2-4d7c-8d3a-a6e438b18841', 'Translation Eng - Mal', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:53.785581+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'നൽകപ്പെടുന്ന ഭാഗം ആശയം ചോരാതെ ഭാഷാന്തരം നടത്തുകയാണ് വേണ്ടത്.', '30 മിനിറ്റ്', 'ആശയ വ്യക്തത, പദ വിജ്ഞാനം, പദ സമ്പത്ത്, സാഹിത്യം') ON CONFLICT DO NOTHING;
