INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('3b28d75d-1a25-406a-9fa0-fcf6417b091b', 'Pencil Drawing', 'f4836f20-4c0c-4748-8ea8-4ce7d0c292bd', 3, false, false, '2026-08-01T06:18:59.528455+00:00', '3ed74f87-6fb2-41c7-8f2d-3de66a9e09c3', NULL, 'off-stage', 1, 'നൽകപ്പെടുന്ന ആശയത്തെ അധികരിച്ചാണ് വരക്കേണ്ടത്. പ്രോഗ്രാം കമ്മിറ്റി നൽകുന്ന A4 പേപ്പറിലാണ് ചിത്രം വരക്കേണ്ടത്.', '1 മണിക്കൂർ', 'ആശയ വ്യക്തത, സംവിധാനം, പ്രയോഗ മികവ് രേഖകളുടെയും ഇരുൾ വെളിച്ചങ്ങളുടെയും സമ്മിശ്രണം, പൂർണ്ണത') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('78bbd9eb-e10b-4c89-a051-bc879b8d094b', 'News Reading', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:53.159419+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'പത്രങ്ങൾ വായിച്ചു ക്രോഡീകരിച്ചാണ് ന്യൂസ് ബുള്ളറ്റിൻ തയ്യാറാക്കി വായിക്കേണ്ടത്.', '10 മിനുട്ട്', 'വാർത്തകളുടെ ക്രോഡീകരണം: 25, വായനയുടെ താളം: 25, ഭാഷാ ശുദ്ധി അക്ഷരസ്‌ഫുടത: 25, വാർത്തയിലെ മുൻഗണനകൾ: 25') ON CONFLICT DO NOTHING;
