INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('50f06317-df75-4944-aba8-983e7b83992f', 'Origami', 'f4836f20-4c0c-4748-8ea8-4ce7d0c292bd', 3, false, false, '2026-08-01T06:18:59.32177+00:00', '3ed74f87-6fb2-41c7-8f2d-3de66a9e09c3', NULL, 'off-stage', 1, 'കടലാസുകൾ മടക്കി വിവിധ രൂപങ്ങൾ സൃഷ്ടിക്കുന്ന മത്സരമാണിത്. ഒരു കടലാസ്മു റിക്കാതെയോ ഒട്ടിക്കാതെയോ വസ്‌തുക്കളുടെ രൂപങ്ങൾ വിവിധ ജ്യാമിതീയ രീതികളിൽ മടക്കിയാണ് രൂപങ്ങൾ നിർമ്മിക്കേണ്ടത് ( മനുഷ്യരുടെയോ മറ്റു ജീവജാലങ്ങളുടെയോ രൂപങ്ങൾ ആവരുത്)', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('2e567db0-1728-492e-b9ec-845ee3248995', 'Water Colouring', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, false, false, '2026-08-01T06:18:55.639625+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'നൽകുന്ന ആശയത്തെ അധികരിച്ചാണ് വരക്കേണ്ടത്. A4 വലുപ്പത്തിലുള്ള പേപ്പറിലാണ് ചിത്രം വരക്കേണ്ടത്.', '1 മണിക്കൂർ', 'ആശയ വ്യക്തത, സംവിധാനം, ചായത്തിൻ്റെ മികവ്, ശൈലി, പൂർണ്ണത') ON CONFLICT DO NOTHING;
