INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('b61d151b-5a1f-46c8-8d95-9d200f2d6356', 'Reading Arabimalayalam', 'f4836f20-4c0c-4748-8ea8-4ce7d0c292bd', 3, false, false, '2026-08-01T06:18:58.725611+00:00', '3ed74f87-6fb2-41c7-8f2d-3de66a9e09c3', NULL, 'off-stage', 1, 'അറബി മലയാളം പുസ്തകങ്ങളിൽ നിന്ന് വിധികർത്താക്കൾ നിർണയിച്ച് നൽകുന്ന ഭാഗം വായിക്കുക.മത്സരത്തിന് 10 മിനുട്ട് മുമ്പ് ഓരോ മത്സരാർത്ഥിക്കും ഭാഗം നിർണയിച്ച് നൽകണം', '5 മിനുട്ട്', 'വായനയുടെ താളം,അക്ഷരസ്ഫുടത,ആശയഗ്രഹണം,ശബ്ദ ക്രമീകീകരണം,ഭാവ വ്യത്യാസം') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('1bee4826-ba0f-4bf0-b223-4efb4ef47fc0', 'Hifz Relay', 'c277087c-e6c2-4961-aa4c-b3a0f5f7735e', 3, false, false, '2026-08-01T06:19:00.931967+00:00', '33c4c6e7-206c-4600-86dd-780cc3097598', NULL, 'off-stage', 1, 'വിധികർത്താക്കൾ നിശ്ചയിക്കുന്ന ആയത്തുകളുടെ തുടർച്ച പാരായണം ചെയ്യുക NB:- സൂറത്തുൽ അ''അല മുതൽ സൂറത്തുന്നാസ് വരെ', '', 'വേഗത ,തജ്‌വീദ്,ശൈലി,സ്വരം') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('e946ac69-00e6-4a22-854a-85f636b73958', 'Pencil Drawing', 'c277087c-e6c2-4961-aa4c-b3a0f5f7735e', 3, false, false, '2026-08-01T06:19:01.536861+00:00', '33c4c6e7-206c-4600-86dd-780cc3097598', NULL, 'off-stage', 1, 'നൽകപ്പെടുന്ന ആശയത്തെ അധികരിച്ചാണ് വരക്കേണ്ടത്. പ്രോഗ്രാം കമ്മിറ്റി നൽകുന്ന A4 പേപ്പറിലാണ് ചിത്രം വരക്കേണ്ടത്.', '1 മണിക്കൂർ', 'ആശയ വ്യക്തത, സംവിധാനം, പ്രയോഗ മികവ് രേഖകളുടെയും ഇരുൾ വെളിച്ചങ്ങളുടെയും സമ്മിശ്രണം, പൂർണ്ണത') ON CONFLICT DO NOTHING;
