INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('28854468-993f-4fb8-b6b2-70c569d83f74', 'Mappilapattu', 'd85a7367-6d26-4504-a26c-e50093111330', 3, true, false, '2026-08-01T06:18:42.74712+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'തനത് മാപ്പിളപ്പാട്ടുകളാണ് ആലപിക്കേണ്ടത്. സലീഖത്ത്,പടപ്പാട്ട്, അനുവദനീയമല്ല.', '5 മിനുട്ട്', 'സ്വരം: 20, സാഹിത്യം: 20, മാപ്പിളത്തനിമ: 20, താളം: 20, ശ്രുതിലയം: 20') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('aaea94ff-1214-4a96-b04f-3c00545c908c', 'Bakthi Ganam', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 3, true, false, '2026-08-01T06:18:52.7802+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'വിശ്വാസം, കർമ്മങ്ങൾ, ആചാരങ്ങൾ തുടങ്ങിയ വിഷയങ്ങളെ ആസ്‌പദമാക്കിയുള്ള ഇസ്‌ലാമിക ഭക്തിഗാനങ്ങളാണ് അവതരിപ്പിക്കേണ്ടത്. ഗാനങ്ങളിലെ പരാമർശിത ആധികാരികമായിരിക്കണം.', '5 മിനുട്ട്', 'സാഹിത്യം: 25, ശ്രുതിലയം: 25, താളം: 25, സ്വരം: 25') ON CONFLICT DO NOTHING;
