INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('c6ede8fb-332f-47af-a3c3-8d4fbbbc3c6e', 'Collage', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 1, false, true, '2026-08-01T06:18:37.994402+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'off-stage', 3, 'കമ്മിറ്റി നൽകുന്ന വിഷയത്തെ അടിസ്ഥാനമാക്കി A3 സൈസിൽ വര, പെയിൻ്റിംഗ്, എഴുത്ത്, ഫോട്ടോ, പത്ര കട്ടിംഗ് എന്നിവകൾ ഉപയോഗിച്ച് ആശയചിത്രം നിർമിക്കുക.', '1 മണിക്കൂർ', 'വിഷയവുമായുള്ള ബന്ധം: 20, കോമ്പിനേഷൻ: 20, പ്രയോഗ രീതി: 20, വിവിധ മാധ്യമങ്ങളുടെ സങ്കലനം: 20, പൂർണത: 20') ON CONFLICT DO NOTHING;
