INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('a71d37c0-666a-45af-8396-a36113dde46b', 'Water Colouring', 'c277087c-e6c2-4961-aa4c-b3a0f5f7735e', 3, false, false, '2026-08-01T06:19:01.754368+00:00', '33c4c6e7-206c-4600-86dd-780cc3097598', NULL, 'off-stage', 1, 'നൽകുന്ന ആശയത്തെ അധികരിച്ചാണ് വരക്കേണ്ടത്. A4 വലുപ്പത്തിലുള്ള പേപ്പറിലാണ് ചിത്രം വരക്കേണ്ടത്.', '1 മണിക്കൂർ', 'ആശയ വ്യക്തത, സംവിധാനം, ചായത്തിൻ്റെ മികവ്, ശൈലി, പൂർണ്ണത') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('eb59aca9-7daf-4951-bd2c-0afcb4249a83', 'Madh Ganam', 'd85a7367-6d26-4504-a26c-e50093111330', 3, true, false, '2026-08-01T06:18:42.946973+00:00', '3d7dc088-dbac-456a-b28e-ee2c0b13d348', NULL, 'stage', 1, 'പ്രവാചകന്മാർ, സ്വഹാബിവര്യർ എന്നിവരെ മദ്ഹ് ചെയ്‌തുള്ള ഗാനങ്ങൾ അവതരിപ്പിക്കുക.', '5 മിനുട്ട്', 'സാഹിത്യം: 25, താളം: 25, ശ്രുതിലയം: 25, സ്വരം: 25') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('4a5f8aaf-4749-4cf9-b39c-625d6d2a2775', 'Language Game', '33b972a7-6477-4a6d-ac27-cc20b47fc1cc', 2, false, false, '2026-08-01T06:18:56.456659+00:00', 'c471dc4d-5eb4-408b-bb99-56b10362554a', NULL, 'off-stage', 1, 'ലാംഗ്വേജ് ഗെയിം : ഭാഷാ പ്രയോഗ ശേഷിയും പദസമ്പത്തും പരിശോധിക്കുന്ന ഈ മത്സരത്തിന് പദ ചങ്ങലനിർമ്മാണവും രണ്ടാം ഘട്ടത്തിൽ നിശ്ചിത പദങ്ങളുപയോഗിച്ച് വാചക നിർമ്മാണവുമാണ് വേണ്ടത്. പദചങ്ങലയിൽ ഒരു പദം ബോർഡിലെഴുതുക.അതിൻ്റെ അവസാന അക്ഷരത്തിൽ തുടങ്ങുന്ന പദം മത്സരാർത്ഥികൾ നിർമിക്കണം. അങ്ങനെ ഓരോ പദത്തിൻ്റെയും അവസാന അക്ഷരത്തിൽ തുടങ്ങുന്ന പദങ്ങൾ നിർമ്മിക്കലാണ് മത്സരം.നാമങ്ങളാണ് പദചങ്ങലയിൽ എഴുതേണ്ടത്. വ്യക്തികളുടെയോ നാടുകളുടെയോ പേരുകൾ പരിഗണിക്കില്ല. അഞ്ച് മിനുട്ട് കൊണ്ട് മത്സരാർത്ഥികൾ പരമാവധി പദങ്ങളെഴുതണം. ചങ്ങല മുറിയുന്നിടത്ത് വെച്ച് മാർക്ക് അവസാനിപ്പിക്കേണ്ടതാണ്', '', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('54bc8ad0-ab5f-4d56-8579-dfb6e0d8af9e', 'Thasneef', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 1, false, true, '2026-08-01T06:18:41.074573+00:00', 'eb0e7540-114e-4218-9d47-2c872090bfbb', NULL, 'off-stage', 5, 'നൽകപ്പെടുന്ന വിഷയത്തിൽ ഗദ്യ രൂപത്തിൽ,അനുവദിക്കുന്ന സമയത്തിനുള്ളിൽ സമർപ്പിക്കുക.അറബി ഭാഷ ആയിരിക്കണം', '12 ദിവസം', 'ആശയം: , ആവിഷ്കാരം: , ഭാഷ: , സംവിധാനം: , റഫറൻസ്: ') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('b9be347a-3c36-4f5b-a448-bf659e5360a4', 'Essay Eng', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 3, false, false, '2026-08-01T06:18:49.541361+00:00', 'eb0e7540-114e-4218-9d47-2c872090bfbb', NULL, 'off-stage', 1, 'വിഷയം മത്സര ഹാളിൽ വച്ച് നൽകും. ഭാഷ : ഇംഗ്ലീഷ്.', '30 മിനിറ്റ്', 'ഭാഷാലാളിത്യം, വസ്‌തുതകളുടെ വിന്യാസം, അവതരണ മികവ്, വിഷയത്തിലുള്ള അറിവ്, റഫറൻസ്') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('c207abf3-95fc-4565-97d1-a5bfc98aea8f', 'Prathikarana Kuripp', '4b1a4259-690b-41ee-aa5d-ee2ab06261dd', 4, false, false, '2026-08-03T10:08:20.904738+00:00', 'eb0e7540-114e-4218-9d47-2c872090bfbb', NULL, 'off-stage', 1, 'പ്രോഗ്രാം കമ്മിറ്റി നൽകുന്ന വിഷയത്തെ ആസ്പദമാക്കി നിങ്ങളുടെ പ്രതികരണങ്ങൾ രേഖപ്പെടുത്തുക.', '20 മിനിറ്റ്', 'ആശയം: , സാഹിത്യം: , ഖണ്ഡികാകരണം: ') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('3caf9852-8687-4e20-a4e4-e661925f57f7', 'Musha''ara Alfiya', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 4, true, false, '2026-08-01T06:18:39.661985+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'stage', 1, 'മുശാഅറ അൽഫിയ്യ: ഇബ്‌നു മാലിക് (റ) വിൻ്റെ കിതാബുൽ അൽഫിയയുടെ ആദ്യ 300 ബൈത്തുകളുടെ ഹിഫ്ള്,ആശയം അടിസ്ഥാനപ്പെടുത്തിയാണ് മത്സരം. മത്സരത്തിന് രണ്ട് റൗണ്ടുകളണ്ടാകും. ആദ്യ റൗണ്ടിൽ ബൈതുകളുടെ മനഃപാഠമാണ് പരിശോധിക്കുക. വിധി കർത്താക്കൾ നിർദ്ദേശിക്കുന്ന ഭാഗം മുതൽ അൽഫിയ്യയിലെ ബൈതുകൾ തുടർച്ചയായി മത്സരാർഥികൾ ചൊല്ലണം. ബൈതുകൾ ചൊല്ലാൻ കഴിയാതെ വരുന്നവർ ഓരോരുത്തരായി പുറത്താകും. അവസാനം മൂന്നു പേർ മാത്രം നില നിൽക്കുമ്പോൾ/ നിശ്ചിത സമയം കഴിയുമ്പോൾ മത്സരത്തിന്റെ രണ്ടാം ഘട്ടത്തിലേക്ക് കടക്കും. രണ്ടാം റൗണ്ടിൽ വിധി കർത്താക്കൾ വ്യാകരണ നിയമങ്ങൾ പറയും. മത്സരാർഥി ഈ നിയമവുമായി ബന്ധപ്പെട്ട ബൈത് ചൊല്ലണം. ഒരാൾക്ക് മൂന്ന് ചാൻസ്. പ്രഥമ ഘട്ടത്തിൽ ആലോചനാ സമയം ഒരു മിനുട്ട്. പിന്നീട് മുപ്പത് സെക്കൻ്റും ആയിരിക്കും', '60 മിനുട്ട്', '') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('fc1bad7d-6859-484d-91e8-1eefd7bbf0a4', 'E - Poster', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 2, false, false, '2026-08-01T06:18:40.673935+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'off-stage', 1, 'നൽകുന്ന പോസ്റ്റർ മാറ്റർ മൊബൈൽ ഫോണിൽ നിശ്ചിത സമയത്തിനുള്ളിൽ ഡിസൈൻ ചെയ്യണം. മൊബൈൽ ഫോണിലെ ഏത് ആപ്പുകളും സോഫ്റ്റ്വെയറുകളും ഇതിന് ഉപയോ ഗിക്കാം. സൃഷ്ടി മൗലികമായിരിക്കണം. ഉപയോഗിച്ച ഇമേജുകൾ കൂടെ അയക്കണം.', '60 മിനിറ്റ്', 'വിഷയവുമായുള്ള പോസ്റ്ററിന്റെ പൊരുത്തവും ആശയാവതരണ പുതുമയും: 25 മാർക്ക്,രൂപങ്ങൾക്ക് തനിച്ചും പരസ്‌പരവും ഉണ്ടായിരി ക്കേണ്ട അനുപാത പൊരുത്തം: 25 മാർക്ക്,ചിത്രം, ടെക്സ്റ്റ് എന്നിവക്ക് നിറങ്ങളുടെ പ്രയോഗം, സാന്ദ്രതാ ഭേദങ്ങൾ, സമത്വവും വൈരുധ്യവും : 25 മാർക്ക്,ഡിജിറ്റൽ സാങ്കേതികതയുടെ വിദഗ്‌ധമായ പ്രയോഗവും ചിത്രത്തിന്റെ ആസ്വാദന ക്ഷമതയും: 25 മാർക്ക്') ON CONFLICT DO NOTHING;
INSERT INTO public.competitions (id, name, category_id, max_participants, is_stage, is_group, created_at, stage_id, announcer_id, competition_type, group_size, rules_description, rules_duration, mark_criteria) VALUES ('687a1716-2d96-4d85-9e9d-2c1108a0f81a', 'Charithrayam', 'fad52ef3-db3d-4a38-9aab-3fd7fed06efa', 3, true, false, '2026-08-01T06:18:38.208611+00:00', '92ebf479-49f5-4a7d-93a5-894c89e342d4', NULL, 'stage', 1, 'വ്യക്തിഗതം, ഒരാൾ ചോദ്യം ചോദിക്കുന്നയാൾ Hunter എന്നും ചോദ്യത്തെ നേരിടുന്ന വ്യക്തി Hunted എന്നും വിളിക്കപ്പെടും. Hunter എതിർ ടീമിലെ മത്സരാർത്ഥിയായിരിക്കും. നിർദ്ദേശിക്കപ്പെടുന്ന മഹത്തുക്കളുടെ ചരിത്രം മത്സരാർത്ഥികൾ പഠിക്കണം. ഇതിൽ ഒരാളെ Hunted മനസ്സിൽ കരുതുകയും പ്രസ്‌തുത വ്യക്തിയുടെ പേര് മത്സരിക്കുന്ന സമയത്ത് ജഡ്ജിന് കൈമാറുകയും ചെയ്യുന്നു. എതിർ ടീമിലെ Hunter യെസ് ഓർ നോ ചോദ്യങ്ങൾ ചോദിച്ച് Hunted മനസ്സിൽ കരുതിയ വ്യക്തിയെ പ്രഖ്യാപിക്കുകയാണ് വേണ്ടത്. മാക്‌സിമം 15 ചോദ്യങ്ങൾ വരെ ചോദിക്കാം. അതിനുശേഷവും Hunter ന് പ്രസ്‌തുത വ്യക്തിയെ പ്രഖ്യാപിക്കാൻ ആയില്ലെങ്കിൽ Hunted ന് പറയാം. ഓരോ ചോദ്യത്തിനും മാക്‌സിമം 15 സെക്കൻഡ് മാത്രമേ ഇടവേള അനുവദിക്കുകയുള്ളൂ. പരമാവധി അഞ്ചു സെക്കൻ്റിനുള്ളിൽ ചോദ്യങ്ങൾക്ക് ഉത്തരം പറയേണ്ടണ്ടതാണ്. Yes/No വാക്കിലാണ് ഉത്തരം നൽകേണ്ടത്.', '60 മിനുട്ട്', 'Hunter ഉത്തരം കണ്ടെത്തിയാൽ അദ്ദേഹത്തിന് 10 മർക്ക്: , Hunter കണ്ടെണ്ടത്തിയിട്ടില്ലെങ്കിൽ Hunted ന് 5 മാർക്ക് ബോണസ് മാർക്കിംഗ്.1-5 ചോദ്യങ്ങൾക്കുള്ളിൽ വ്യക്തിയെ കണ്ടെത്താനായാൽ: 10 മാർക്.6-10 ചോദ്യങ്ങൾക്കുള്ളിൽ വ്യക്തിയെ കണ്ടെത്താനായാൽ : 8 മാർക്.11-15 ചോദ്യങ്ങൾക്കുള്ളിൽ വ്യക്തിയെ കണ്ടെത്താനായാൽ : 5 മാർക്.Hunterക്ക് ചോദ്യമായിട്ട് ഉദ്ദേശിക്കപ്പെട്ട വ്യക്തിയുടെ പേര് / അദ്ദേഹത്തിൻ്റെ സൂചന പേര് ഒറ്റ പ്രാവശ്യം ചോദിക്കാവുന്നതാണ് Hunted നൽകുന്ന വിവരങ്ങൾ ശരിയായിരിക്കണം') ON CONFLICT DO NOTHING;
